{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "Levocetirizine, a zwitterionic piperazine with a carboxylic acid, showed the lowest brain H1-receptor occupancy among second-generation antihistamines and is non-sedating, directly demonstrating poor CNS access for an acid/amine zwitterion.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Bepotastine, a zwitterionic piperidine bearing a carboxylic acid side chain, showed only 16.6% cortical H1RO and was classified as low permeability, supporting poor CNS exposure for the query's piperidine-acid zwitterion.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Cetirizine, a close zwitterionic analogue, had very low brain concentrations after IV dosing due to P-gp-mediated efflux, indicating that acid/amine zwitterions of this type are subject to BBB efflux and limited CNS distribution.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "3-[18F]FEPB, a high-transfer basic ester, showed low non-receptor-mediated brain uptake in rodents, providing additional direct evidence that ionizable amine-containing molecules in this transfer context can have poor CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "A zwitterionic piperidine carboxylic acid (4g) achieved a CSF/unbound plasma ratio of 0.7 and was labeled permeable in rats, showing that this general zwitterionic class is not universally CNS-impermeable and introducing uncertainty.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a fully ionized zwitterionic benzimidazole-piperidine carboxylic acid with very low predicted passive permeability. The most transferable and mechanistically relevant direct evidence comes from zwitterionic antihistamines (levocetirizine, bepotastine, cetirizine), which show low brain uptake, low receptor occupancy, and P-gp efflux. One zwitterionic piperidine acid (4g) was permeable, but the query's larger size, lower logD, and additional polar ethoxyethyl/benzimidazole features make it more similar to the poor penetrants. Therefore, meaningful CNS access is unlikely.",
  "evidence_gaps": [
    "No direct brain/CSF data for the exact query molecule.",
    "C02 sufentanil CSF record is ambiguous for the meaningful-access endpoint and was not used as a primary anchor.",
    "Unknown whether the query is a substrate for an uptake transporter that could overcome low passive permeability.",
    "The positive zwitterionic piperidine acid (C09) indicates that not all such compounds fail; query-specific permeability data would be needed to confirm."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

